SELECT *
FROM participate_project as pp join student_information as si on pp.student_number = si.student_number


        AND pp.student_name = #{studentName}


        AND pp.student_number = #{studentNumber}


        AND si.classes = #{classes}


        AND si.grade = #{grade}


        AND si.major = #{major}


        AND si.college = #{college}
